export function samCard(S, forDefense) {
  const tips = (forDefense ? USE : FIGHT)[S.type] || [];
  return { title: `${S.name}`, body: `<h4>Что это</h4><p>${S.guide}</p><table class="tt">${S.specs.map(([a, b]) => `<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</table>
    <h4>Наведение</h4><p>${SAM_TYPE[S.type]}${S.radar ? '' : ' · без РЛС — на СПО не виден'}. В игре: ${(S.rmin / 1000).toFixed(1)}–${(S.rmax / 1000).toFixed(1)} км, высоты ${S.hmin}–${S.hmax} м.</p>
    <h4>${forDefense ? 'Как воевать' : 'Что делать'}</h4><ol>${tips.map((t) => `<li>${t}</li>`).join('')}</ol>` };
}
export function weaponCard(W) {
  const how = { bomb: ['Кружок на экране — точка падения. Выведите его на цель и сбрасывайте.', 'Чем ниже и медленнее — тем точнее; но низко — опасно от пушек.'],
    lgb: ['Контейнер захватит цель сам: до неё 1–18 км, вы не ниже 400 м, цель не закрыта домами («ЦЕЛЬ» / R — другая цель).', 'Сбросьте, когда в панели оружия «В ЗОНЕ».', 'Держите подсвет до попадания: лазер ● горит, пока контейнер видит точку. Корпус («МАСКИРОВКА») и здания его срывают.'],
    tvb: ['Нужен захват контейнером до сброса (он захватывает сам) — ТВ-головка запоминает картинку.', 'После сброса можно уходить. Ночью не работает.'],
    agm: W.seeker === 'tv' ? ['Дождитесь захвата контейнером, нос на цель (в поле ГСН), пуск — дальше ракета сама.', 'Ночью ТВ-головка не видит.'] : ['Захват контейнером, пуск, подсвет до попадания — как у лазерной бомбы.'],
    arm: [`Пуск по включённой РЛС впереди (в поле ГСН ±${W.fov}°) — на СПО она должна быть.`, W.mmw ? 'Миллиметровая ГСН на конце находит даже выключенную машину, если та не уехала.' : W.mem ? 'Помнит место станции: выключение РЛС не спасёт, только переезд.' : 'Памяти нет: если расчёт выключит РЛС, ракета промахнётся.'],
    gps: ['Координаты — захват контейнером или ближайшая цель задания впереди.', 'Сбрасывать, когда «В ЗОНЕ»; дальше — сама, ночью и в облаках.', 'В зоне станции подавления навигации уйдёт на десятки метров.'],
    cruise: ['Пуск издалека по координатам цели: ракета идёт на малой высоте, огибая дома.', 'Её видят только станции, которые различают низкие цели, — «Тор», «Панцирь».'],
    decoy: ['Пустите перед ударом: для РЛС — ещё один самолёт, ПВО тратит на неё ракеты.'],
    ecm: ['Работает весь вылет: РЛС видят вас ближе и чаще теряют. Против помехозащищённых станций — слабее.'] }[W.kind];
  return { title: W.name, body: `<h4>Что это</h4><p>${W.guide}</p><table class="tt">${W.specs.map(([a, b]) => `<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</table>
    <h4>Как применять</h4><ol>${how.map((t) => `<li>${t}</li>`).join('')}</ol><p class="dim">${AG_KIND[W.kind]}</p>` };
}

// ═════════════ Уроки ═════════════
// урок ПВО: c.unit(C) — комплекс; показ — «АВТО» оператора ведёт его по первому самолёту, потом — игрок (c.need сбитых);
// c.role / c.alt / c.R / c.n — кто и как летит (по c.n самолётов за раз), c.dist — от склада боеприпасов
function DL(c) {
  const spawnP = (C) => { const t = objOf(C, 'tpp'); for (let i = 0; i < (c.n || 1); i++) { const a = C.raid.spawn(c.role || 'bomber', t, Math.random() * 6.28, i * 5, c.R || 11000); if (c.alt) a.cruise = c.alt; else if (!c.role) a.cruise = 2200; } };
  return { id: c.id, sec: c.sec || 'Комплексы', name: c.name, desc: c.desc, era: c.era,
    intro: (C) => { const S = SAM[c.unit(C)]; return card(S.name, c.how(S), c.errs(S), '<p class="dim">Сначала — показ: «АВТО» сам ведёт комплекс по первой цели. Потом — вы.</p>'); },
    def: (C) => ({ budget: 0, waves: 1, plan: false, op: 0, hold: true, units: [[c.unit(C), ...near(C, objOf(C, 'tpp'), c.dist || 600)]], wave: () => spawnP(C) }),
    tick(T, C) {
      const u = C.S.units[0], D = C.ctrl.inner, d = T.d, need = c.need || 1;
      if (!u || u.dead) return T.fail('Комплекс уничтожен.');
      if (u && (u.reloadT > 0 || u.ammo <= 0)) { u.ammo = u.S.ammo; u.reloadT = 0; } // в обучении — без перезарядки
      if (d.auto0 === undefined) d.auto0 = C.auto;
      d.downs = d.downs || 0;
      if (T.s === 0) {
        C.auto = true;
        T.hint(`<b>Показ.</b> ${c.demoHint(C, u)} <span class="dim">«АВТО» назначает цель и стреляет сам — смотрите.</span>`);
        if (d.downs >= Math.min(need, c.n || 1) || T.st > 100) { C.auto = d.auto0; d.base = d.downs; T.next(); }
      } else if (d.downs - (d.base || 0) >= need) { T.hint(`<b>${c.win}</b>`); d.win = d.win || T.t; if (T.t - d.win > 3) T.done(); }
      else T.hint(`<b>Теперь вы.</b> ${c.hint(T, C, u, D)}`);
      if (u && !u.dead && !C.raid.planes.some((a) => !a.dead && !a.out) && T.st > 2) spawnP(C);
    },
    hooks: (T) => (c.mun ? { wpnEnd: (w, res) => { if (res.intercepted) T.d.downs = (T.d.downs || 0) + 1; } } // счёт — сбитые бомбы и ракеты
      : { planeDown: () => { T.d.downs = (T.d.downs || 0) + 1; }, ...(c.hooks ? c.hooks(T) : {}) }) };
}
// Каждый урок открывается карточкой «Как это работает в игре» + «Типичные ошибки» (игра на паузе), уроки с оружием —
// показ (автопилот и «АВТО» применяют его по учебной цели, камера — за оружием), затем то же самое делает игрок по другой цели.
const li = (a) => a.map((t) => `<li>${t}</li>`).join('');
export const card = (title, how, errs, extra = '') => ({ title, body: `<h4>Как это работает в игре</h4><ul>${li(how)}</ul><h4>Типичные ошибки</h4><ul>${li(errs)}</ul>${extra}` });
// точка захода: d м от объекта (со стороны центра карты), высота alt над землёй, нос — на объект
// (ang — пеленг точки захода от объекта, 0 — +z: например, с окраины, а не через высотки центра)
function approach(C, o, d, alt, ang) {
  let vx = -o.x, vz = -o.z; const L = Math.hypot(vx, vz);
  if (ang !== undefined) { vx = Math.sin(ang); vz = Math.cos(ang); } else if (L < 2000) { vx = 0; vz = 1; } else { vx /= L; vz /= L; }
  const x = o.x + vx * d, z = o.z + vz * d;
  return { x, y: C.city.groundH(x, z) + alt, z, yaw: Math.atan2(vx, vz) };
}
// урок с оружием: c.key(C) — оружие, c.demo / c.prac — [объект, дальность захода, высота], c.how(W) / c.errs(W) — карточка,
// c.demoHint / c.hint — подсказки, c.win — итог
function WL(c) {
  return { id: c.id, sec: c.sec || 'Бомбы', name: c.name, desc: c.desc,
    intro: (C) => { const W = AG[c.key(C)]; return card(W.name, c.how(W), c.errs(W), `<p class="dim">Сначала — показ: автопилот сам применит оружие по учебной цели. Потом — вы.</p>`); },
    air: (C) => ({ items: [[c.key(C), c.n || 2]], pod: !!c.pod, targets: [c.demo[0], c.prac[0]], defense: () => {}, spawn: approach(C, objOf(C, c.demo[0]), c.demo[1], c.demo[2], c.demo[3]) }),
    tick(T, C) {
      const a = C.ctrl.inner, W = AG[c.key(C)], dO = objOf(C, c.demo[0]), pO = objOf(C, c.prac[0]);
      const fly = C.S.wpns.some((w) => w.owner === a.craft), empty = !a.loadout.some((l) => l.n > 0) && !fly;
      if (T.s === 0) { // показ
        if (!T.d.demo) { T.d.demo = 1; for (const o of [dO, pO]) o.hp = Math.min(o.hp, W.dmg * 0.25); /* учебные цели — с одного попадания */ a.retarget([dO]); a.place(approach(C, dO, c.demo[1], c.demo[2], c.demo[3])); a.demo({ pt: dO, alt: c.demo[2] }); }
        if (fly) a.setCam(3);
        if (empty) a.rearm();
        T.hint(`<b>Показ.</b> ${fly ? 'Оружие ушло — камера следит за ним.' : c.demoHint(C, W, a)} <span class="dim">Автопилот и «АВТО» всё делают сами.</span>`);
        if (dO.dead && !fly) { T.d.wait = T.d.wait || T.st; if (T.st - T.d.wait > 2.5) T.next(); } else if (T.st > 90) T.next(); // не вышло — к практике
        return;
      }
      if (T.s === 1) { a.demo(null); a.setCam(0); a.rearm(); a.retarget([pO]); a.place(approach(C, pO, c.prac[1], c.prac[2], c.prac[3])); a.say('Теперь вы', 2); T.next(); return; }
      if (pO.dead) { T.hint(`<b>${c.win}</b>`); T.d.win = T.d.win || T.t; if (T.t - T.d.win > 3) T.done(); return; }
      if (empty) { a.rearm(); a.say('Подвеска пополнена (обучение)', 1.5); }
      T.hint(`<b>Теперь вы.</b> ${c.hint(T, C, a, pO, W)}`);
    } };
}
// air(C) / def(C) — опции режима; tick(T) — шаги: T.hint(), T.done(), T.ask(карточка), T.t — время урока, T.s — номер шага, T.d — данные
